mapper.select:
SELECT id, type, title, cover, price, min_price AS minPrice, max_price AS maxPrice, total_sales AS totalSales, status, purpose, anchor, stock, created_at FROM products WHERE type = 'mass'
AND status = #{status}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR anchor LIKE CONCAT('%', #{keyword}, '%')
OR id = CAST(#{keyword} AS BIGINT)
)
ORDER BY id DESC
